pre-actions.script:
const marketing=ec.resource.script('component://mr-pass/screen/Marketing/Marketing.js')
const found=marketing.portal.attempt('getMarketingPage',{siteId:resolvedSiteId,routePath:String(routePath || ''),
    locale:ec.user.locale ? String(ec.user.locale) : null})
if(found.error){
    if(found.error.kind!=='NotFound')throw Object.assign(new Error(found.error.message),{moquiErrorKind:found.error.kind})
    throw Object.assign(new Error('Page not found'),{moquiErrorKind:'NotFound'})
}
landingPage=found.result.page
// P15: a tracking link's code on the page's address records one visit (never a click, a consent or a conversion)
const tracking=ec.resource.script('component://mr-pass/script/TrackingLib.js')
if(tc && tracking.codePattern.test(String(tc))){
    const request=ec.web.request
    const robot=tracking.automated(request)
    tracking.attempt('recordTrackingEvent',{siteId:resolvedSiteId,code:String(tc),kind:robot ? 'visitFetch' : 'visit',
        visitorKey:!robot && !tracking.doNotTrack(request) ? tracking.heldKey(request) : null})
}
marketingBase=passBases?.marketing ?? '/marketing'
// each part in order: the page's text sanitized again, or an embedded component the site offers now (else nothing)
landingParts=[]
for(const part of landingPage.parts || []){
    if(part.kind==='html')landingParts.push({kind:'html',html:ec.resource.theme.sanitizeRichText(String(part.html || ''))})
    else if(part.kind==='subscribe'){
        const offer=marketing.portal.attempt('getMarketingPublication',{siteId:resolvedSiteId,contactListId:part.contactListId})
        if(!offer.error && offer.result.topics.length)
            landingParts.push({kind:'subscribe',topic:offer.result.topics[0],organizationName:offer.result.organizationName,
                operationId:marketing.portal.operationId()})
    }else if(part.kind==='event'){
        // P16: a registration offer published on this site, as a card linking its Event page
        const offer=marketing.portal.attempt('getMarketingEvent',{siteId:resolvedSiteId,registrationPolicyId:part.registrationPolicyId})
        if(!offer.error)
            landingParts.push({kind:'event',registrationPolicyId:offer.result.event.registrationPolicyId,title:offer.result.event.title,
                whenText:offer.result.event.startText,location:offer.result.event.location || (offer.result.event.online ? 'Online' : ''),
                availability:offer.result.event.availability})
    }else if(part.kind==='form'){
        const form=marketing.portal.attempt('getMarketingForm',{siteId:resolvedSiteId,publicationId:part.publicationId})
        if(!form.error && form.result.form.publicationId)
            landingParts.push({kind:'form',publicationId:form.result.form.publicationId,title:form.result.form.title,
                intro:form.result.form.intro})
    }
}
